// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IModelOracle {
    function getInferenceResult(bytes32 modelId, bytes calldata input) external returns (uint256);
}

interface IRewardDistributor {
    function distributeReward(address recipient, uint256 amount) external;
}

contract MLInferenceServer is AccessControl, ReentrancyGuard {
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant MODEL_PROVIDER_ROLE = keccak256("MODEL_PROVIDER_ROLE");

    struct InferenceRequest {
        address requester;
        bytes32 modelId;
        bytes input;
        uint256 stake;
        bool completed;
        uint256 result;
    }

    struct ModelConfig {
        address provider;
        uint256 baseFee;
        uint256 accuracyBounty;
        bool active;
    }

    mapping(uint256 => InferenceRequest) public requests;
    mapping(bytes32 => ModelConfig) public models;
    mapping(address => uint256) public providerBalances;
    mapping(address => uint256) public userDeposits;
    mapping(uint256 => bool) public bountyClaimed;

    uint256 public nextRequestId;
    IModelOracle public oracle;
    IRewardDistributor public rewardDistributor;

    event InferenceRequested(uint256 indexed requestId, bytes32 modelId);
    event InferenceCompleted(uint256 indexed requestId, uint256 result);
    event ProviderRewarded(address indexed provider, uint256 amount);

    constructor(address _oracle, address _rewardDistributor) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(OPERATOR_ROLE, msg.sender);
        oracle = IModelOracle(_oracle);
        rewardDistributor = IRewardDistributor(_rewardDistributor);
    }

    function registerModel(
        bytes32 modelId,
        uint256 baseFee,
        uint256 accuracyBounty
    ) external onlyRole(MODEL_PROVIDER_ROLE) {
        require(!models[modelId].active, "Model already registered");
        models[modelId] = ModelConfig({
            provider: msg.sender,
            baseFee: baseFee,
            accuracyBounty: accuracyBounty,
            active: true
        });
    }

    function deposit() external payable {
        userDeposits[msg.sender] += msg.value;
    }

    function requestInference(
        bytes32 modelId,
        bytes calldata input
    ) external returns (uint256) {
        ModelConfig memory config = models[modelId];
        require(config.active, "Model not active");
        require(userDeposits[msg.sender] >= config.baseFee, "Insufficient deposit");

        userDeposits[msg.sender] -= config.baseFee;

        uint256 requestId = nextRequestId++;
        requests[requestId] = InferenceRequest({
            requester: msg.sender,
            modelId: modelId,
            input: input,
            stake: config.baseFee,
            completed: false,
            result: 0
        });

        emit InferenceRequested(requestId, modelId);
        return requestId;
    }

    function fulfillInference(
        uint256 requestId
    ) external nonReentrant onlyRole(OPERATOR_ROLE) {
        InferenceRequest storage req = requests[requestId];
        require(!req.completed, "Already completed");

        uint256 result = oracle.getInferenceResult(req.modelId, req.input);
        req.result = result;
        req.completed = true;

        ModelConfig memory config = models[req.modelId];
        providerBalances[config.provider] += req.stake;

        emit InferenceCompleted(requestId, result);
    }

    function _settleAccuracyBounty(
        bytes32 modelId,
        address provider,
        uint256 bountyAmount
    ) internal {
        providerBalances[provider] += bountyAmount;
        rewardDistributor.distributeReward(provider, bountyAmount);
        emit ProviderRewarded(provider, bountyAmount);
    }

    function claimAccuracyBounty(
        uint256 requestId,
        bytes calldata proof
    ) external nonReentrant {
        InferenceRequest storage req = requests[requestId];
        require(req.completed, "Not completed");
        require(!bountyClaimed[requestId], "Already claimed");

        ModelConfig memory config = models[req.modelId];
        require(msg.sender == config.provider, "Not provider");
        require(config.accuracyBounty > 0, "No bounty");

        bountyClaimed[requestId] = true;

        // Verify accuracy proof via oracle callback
        uint256 verification = oracle.getInferenceResult(
            keccak256(abi.encodePacked("verify", req.modelId)),
            proof
        );
        require(verification == 1, "Proof invalid");

        _settleAccuracyBounty(req.modelId, config.provider, config.accuracyBounty);
    }

    function withdrawProviderBalance() external nonReentrant {
        uint256 balance = providerBalances[msg.sender];
        require(balance > 0, "No balance");
        providerBalances[msg.sender] = 0;
        (bool success, ) = msg.sender.call{value: balance}("");
        require(success, "Transfer failed");
    }

    function withdrawDeposit(uint256 amount) external nonReentrant {
        require(userDeposits[msg.sender] >= amount, "Insufficient balance");
        userDeposits[msg.sender] -= amount;
        (bool success, ) = msg.sender.call{value: amount}("");
        require(success, "Transfer failed");
    }

    receive() external payable {}
}
